using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace GearLab {
 public static class CompoundUiTests {public static int Run(string folder){Directory.CreateDirectory(folder);try{using(var form=new TrainDesignerForm(CompoundReducer.Example())){form.ShowInTaskbar=false;form.Opacity=0;form.Show();Application.DoEvents();form.CompoundVerify(folder);form.WorkspaceApproveClose();form.Close();}using(var form=new TrainDesignerForm(TransmissionTrain.Example())){form.ShowInTaskbar=false;form.Opacity=0;form.Show();Application.DoEvents();form.PtkWorkflowVerify(folder);form.WorkspaceApproveClose();form.Close();}File.WriteAllText(Path.Combine(folder,"compound-ui-results.json"),"{\"Passed\":true}");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"compound-ui-error.txt"),ex.ToString());return 1;}finally{SceneAnimation.Enabled=false;}}}
 public sealed partial class TrainDesignerForm {
  internal void PtkWorkflowVerify(string folder){
   list.SelectedIndex=0;ChangeStageKind(4);list.SelectedIndex=1;ChangeStageKind(3);commonHousing.Checked=true;if(!housingProperties.Enabled)throw new Exception("Housing properties stay disabled after activation");Calculate();
   if(solution.Valid||!status.Text.Contains("Согласовать валы"))throw new Exception("Shaft mismatch must identify the available repair action: "+status.Text);
   MatchShafts();Calculate();if(!solution.Valid||solution.Compound==null)throw new Exception("Type selection workflow failed: "+string.Join(";",solution.Errors));
   if(document.Stages[1].Parameters.Shaft!=document.Stages[0].Parameters.OutputShaft)throw new Exception("Shaft action failed");History(false);if(document.Stages[1].Parameters.Shaft!=5)throw new Exception("Undo shaft matching failed");History(true);if(!solution.Valid||document.Stages[1].Parameters.Shaft!=8)throw new Exception("Redo shaft matching failed");
   if(!stageNumbers.ContainsKey("Shaft")||!stageNumbers.ContainsKey("OutputShaft"))throw new Exception("Shaft fields missing");
   viewer.Scene.Root.Measure(new System.Windows.Size(1000,800));viewer.Scene.Root.Arrange(new System.Windows.Rect(0,0,1000,800));
   SceneAnimation.Enabled=true;viewer.Scene.SetResult(null,false);viewer.Scene.SetResult(solution.Scene,false);
   if(!viewer.Scene.Animating||!viewer.Scene.Nodes.Any(n=>n.Transform.Matrix!=n.Pose))throw new Exception("Assembly presentation did not start");
   AwaitPresentation();if(viewer.Scene.Nodes.Any(n=>n.Transform.Matrix!=n.Pose))throw new Exception("Presentation altered final part poses");
   var original=viewer.Scene.Nodes.ToDictionary(n=>n.Part.Id,n=>n.Pose);viewer.SetExploded(true);if(!viewer.Scene.Animating)throw new Exception("Exploded presentation did not start");AwaitPresentation();
   foreach(var node in viewer.Scene.Nodes){double expected=CompoundExport.Explode(solution.Scene,node.Part);if(Math.Abs(node.Pose.OffsetZ-original[node.Part.Id].OffsetZ-expected)>1e-7)throw new Exception("Compound explosion group lost: "+node.Part.Id);}
   viewer.SetExploded(false);System.Threading.Thread.Sleep(80);Application.DoEvents();viewer.SetExploded(true);AwaitPresentation();viewer.SetExploded(false);AwaitPresentation();
   foreach(var node in viewer.Scene.Nodes)if(node.Pose!=original[node.Part.Id]||node.Transform.Matrix!=node.Pose)throw new Exception("Interrupted animation changed model pose");
   viewer.Scene.SavePng(Path.Combine(folder,"ptk-workflow-3d.png"),1000,800);viewer.SetExploded(true);viewer.Scene.ConfigureSection(0,0,true);if(viewer.Scene.Animating)throw new Exception("Section must finish presentation");viewer.Scene.ConfigureSection(-1,0,true);SceneAnimation.Enabled=false;viewer.SetExploded(false);
  }
  void AwaitPresentation(){var wait=System.Diagnostics.Stopwatch.StartNew();while(viewer.Scene.Animating&&wait.ElapsedMilliseconds<4000){System.Threading.Thread.Sleep(15);Application.DoEvents();}if(viewer.Scene.Animating)throw new Exception("Presentation did not finish");}
  internal void CompoundVerify(string folder){Calculate();if(solution==null||!solution.Valid||solution.Compound==null)throw new Exception("Compound UI model missing");if(!commonHousing.Checked||housingProperties.SelectedObject!=document.SharedHousing)throw new Exception("Housing controls not bound");using(var bmp=new Bitmap(620,720))using(var schematic=new CompoundSectionPanel{Size=new Size(620,720),Solution=solution}){schematic.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(Path.Combine(folder,"compound-section.png"));}viewer.Scene.SetResult(null,false);viewer.Scene.SetResult(solution.Scene,false);viewer.Scene.Root.Measure(new System.Windows.Size(1000,800));viewer.Scene.Root.Arrange(new System.Windows.Rect(0,0,1000,800));viewer.Fit();if(!viewer.Scene.Ready||viewer.Scene.Nodes.Count!=solution.Scene.Model.Parts.Count)throw new Exception("3D scene incomplete: "+viewer.Scene.Error);viewer.Scene.SavePng(Path.Combine(folder,"compound-3d.png"),1000,800);viewer.SetExploded(true);viewer.Scene.SavePng(Path.Combine(folder,"compound-exploded.png"),1000,800);viewer.SetExploded(false);}
 }
}
